size_t tlsf_largest_free_block(tlsf_t tlsf)
{
    if (tlsf == NULL) {
        return 0;
    }
    control_t* control = tlsf_cast(control_t*, tlsf);
    if (control->fl_bitmap == 0) {
        return 0;
    }
    const int fl = tlsf_fls(control->fl_bitmap);
    const int sl = tlsf_fls(control->sl_bitmap[fl]);
    tlsf_assert(sl >= 0 && "occupied first-level bin has no second-level bin");
    const block_header_t* block = control->blocks[fl * control->sl_index_count + sl];
    tlsf_assert(block != &control->block_null && block_is_free(block));
    /* All blocks in this highest occupied bin have the same fit-rounded size. */
    return tlsf_fit_size(tlsf, block_size(block));
}

