size_t multi_heap_get_largest_free_block(multi_heap_handle_t heap)
{
#if CONFIG_HEAP_TLSF_USE_ROM_IMPL || defined(MULTI_HEAP_POISONING)
    /* Preserve ROM ABI and poisoning overhead without relying on private layout. */
    multi_heap_info_t info;
    multi_heap_get_info(heap, &info);
    return info.largest_free_block;
#else
    if (heap == NULL) {
        return 0;
    }
    multi_heap_internal_lock(heap);
    const size_t largest = tlsf_largest_free_block(heap->heap_data);
    multi_heap_internal_unlock(heap);
    return largest;
#endif
}

