#if CONFIG_ESPHOME_HEAP_FAST_LARGEST_BLOCK
/* Opt-in runtime comparison starts with the unchanged implementation. */
static atomic_bool fast_largest_free_block_enabled = ATOMIC_VAR_INIT(false);

void heap_caps_set_fast_largest_free_block(bool enabled)
{
    atomic_store_explicit(&fast_largest_free_block_enabled, enabled, memory_order_relaxed);
}

bool heap_caps_get_fast_largest_free_block_enabled(void)
{
    return atomic_load_explicit(&fast_largest_free_block_enabled, memory_order_relaxed);
}
#endif

size_t heap_caps_get_largest_free_block( uint32_t caps )
{
#if CONFIG_ESPHOME_HEAP_FAST_LARGEST_BLOCK
    /* Select one implementation for this complete call, including all heaps. */
    if (atomic_load_explicit(&fast_largest_free_block_enabled, memory_order_relaxed)) {
        size_t largest = 0;
        heap_t *heap;
        SLIST_FOREACH(heap, &registered_heaps, next) {
            if (heap_caps_match(heap, caps)) {
                const size_t candidate = multi_heap_get_largest_free_block(heap->heap);
                largest = MAX(largest, candidate);
                /* Keep the existing per-iteration accumulated owner adjustment. */
                largest -= largest ? MULTI_HEAP_BLOCK_OWNER_SIZE() : 0;
            }
        }
        return largest;
    }
#endif
    multi_heap_info_t info;
    heap_caps_get_info(&info, caps);
    return info.largest_free_block;
}

